async function listListings(env, { limit = 9999, offset = 0 } = {}) {
  const ownSeed = typeof TRIO_HEPSIEMLAK_SEED !== "undefined" ? TRIO_HEPSIEMLAK_SEED : [];
  const partnerSeed = typeof TRIO_PARTNER_HEPSIEMLAK_SEED !== "undefined" ? TRIO_PARTNER_HEPSIEMLAK_SEED : [];
  const seed = [...ownSeed, ...partnerSeed].map(row => ({...row, area: normalizeAreaText(row.area), location_parts: parseLocationParts(row.area), price_value: parseMoney(row.price), url: normalizeExternalUrl(row.url), instagram_url: normalizeExternalUrl(row.instagram_url)}));
  if (!env.DB) return [...seed,...memoryListings.filter(row=>!seed.some(item=>item.url&&item.url===row.url))].slice(Number(offset), Number(offset) + Number(limit)).map(row=>({...row,trio_checked_at:memoryListingSourceReviews.get(row.url)||null}));
  try {
    const [result, assetResult] = await Promise.all([
      env.DB.prepare("SELECT l.title,l.area,l.type,l.detail,l.price,l.official_url AS url,l.instagram_url,l.eids_verified,r.reviewed_at FROM listings l LEFT JOIN listing_source_reviews r ON l.official_url = r.listing_url ORDER BY l.id DESC LIMIT ? OFFSET ?").bind(Math.max(1, Math.min(Number(limit) || 25, 200)), Math.max(0, Number(offset) || 0)).all(),
      env.DB.prepare("SELECT source_listing_id,description,details_json,photos_json FROM listing_assets").all(),
    ]);
    let assets = new Map();
    try { assets = new Map((assetResult.results || []).map(asset => [String(asset.source_listing_id), asset])); } catch (_) {}
    const databaseRows=(result.results||[]).map(row=>{
      const sourceId=String(row.url||"").match(/-(\d{6,})\//i)?.[1];
      const asset=sourceId ? assets.get(sourceId) : null;
      if(asset?.description)row.description=asset.description;
      if(asset?.details_json){try{row.details=JSON.parse(asset.details_json)}catch(_) {}}
      if(asset?.photos_json){try{row.images=JSON.parse(asset.photos_json)}catch(_) {}}
      return row;
    });
    const safeDatabaseRows = databaseRows.map(row => ({...row, area: normalizeAreaText(row.area), location_parts: parseLocationParts(row.area), price_value: parseMoney(row.price), url: normalizeExternalUrl(row.url), instagram_url: normalizeExternalUrl(row.instagram_url)}));
    const combined=seed.length ? [...seed,...safeDatabaseRows.filter(row=>!seed.some(item=>item.url===row.url))] : safeDatabaseRows;
    return combined.map(row=>({...row,trio_checked_at:row.reviewed_at||null}));
  } catch (error) {
    throw error;
  }
}
