function normalizePhone(value){let digits=String(value||"").replace(/[^0-9]/g,"");if(digits.startsWith("00"))digits=digits.slice(2);if(digits.length===12&&digits.startsWith("90"))return digits;if(digits.length===11&&/^0[2-5]/.test(digits))return "90"+digits.slice(1);if(digits.length===10&&/^[2-5]/.test(digits))return "90"+digits;return digits}
function extractWhatsAppMessages(payload){
  const rows=[];
  for(const entry of Array.isArray(payload?.entry)?payload.entry:[]){
    for(const change of Array.isArray(entry?.changes)?entry.changes:[]){
      const value=change?.value||{};
      const contacts=Array.isArray(value.contacts)?value.contacts:[];
      for(const message of Array.isArray(value.messages)?value.messages:[]){
        const contact=contacts.find(item=>String(item?.wa_id||"")===String(message?.from||""))||contacts[0]||{};
        const body=message?.text?.body||message?.button?.text||message?.interactive?.button_reply?.title||message?.interactive?.list_reply?.title||"";
        rows.push({message_id:String(message?.id||`${message?.from||"unknown"}:${message?.timestamp||Date.now()}`),from_phone:String(message?.from||contact?.wa_id||""),sender_name:String(contact?.profile?.name||"WhatsApp müşterisi"),body:String(body).slice(0,2000),message_type:String(message?.type||"unknown"),received_at:message?.timestamp?new Date(Number(message.timestamp)*1000).toISOString():new Date().toISOString()});
      }
    }
  }
  return rows.filter(row=>row.from_phone&&row.body);
}
async function listWhatsAppMessages(env){
  if(!env.DB)return memoryWhatsAppMessages;
  const result=await env.DB.prepare("SELECT message_id,from_phone,sender_name,body,message_type,received_at,customer_id,customer_name,processed FROM whatsapp_messages ORDER BY id DESC LIMIT 100").all();
  return result.results||[];
}
async function ingestWhatsAppPayload(env,payload){
  const rows=extractWhatsAppMessages(payload);let accepted=0;
  for(const row of rows){
    if(!env.DB){
      if(memoryWhatsAppMessages.some(item=>item.message_id===row.message_id))continue;
      memoryWhatsAppMessages.unshift({...row,customer_name:null,processed:0});
      accepted++;continue
    }
    const exists=await env.DB.prepare("SELECT id FROM whatsapp_messages WHERE message_id=? LIMIT 1").bind(row.message_id).first();
    if(exists)continue;
    await env.DB.prepare("INSERT INTO whatsapp_messages (message_id,from_phone,sender_name,body,message_type,received_at,customer_name,processed) VALUES (?,?,?,?,?,?,NULL,0)").bind(row.message_id,row.from_phone,row.sender_name,row.body,row.message_type,row.received_at).run();
    accepted++;
  }
  return {accepted,received:rows.length};
}
async function reviewWhatsAppMessage(env,input){
  const messageId=String(input?.message_id||"").trim().slice(0,200);
  const decision=String(input?.decision||"");
  if(!messageId)invalidPayload(["message_id"]);
  if(!["accept","ignore"].includes(decision))invalidPayload(["decision"]);
  const confirmation=decision==="accept"?"PROCESS_WHATSAPP_MESSAGE":"IGNORE_WHATSAPP_MESSAGE";
  if(String(input?.confirmation||"")!==confirmation){const error=new Error("confirmation_required");error.status=400;error.fields=["confirmation"];throw error}
  if(!env.DB){
    const message=memoryWhatsAppMessages.find(item=>item.message_id===messageId);
    if(!message){const error=new Error("message_not_found");error.status=404;throw error}
    if(Number(message.processed)!==0){const error=new Error("message_already_reviewed");error.status=409;throw error}
    if(decision==="ignore"){message.processed=2;return{message_id:messageId,processed:2}}
    const existing=await findCustomerByPhone(env,message.from_phone);
    const name=String(existing?.name||message.sender_name||"WhatsApp müşterisi").trim().slice(0,120)||"WhatsApp müşterisi";
    const customer=existing||await addCustomer(env,{name,phone:message.from_phone,need:"WhatsApp mesajı • manuel inceleme",stage:"Yeni talep",last:message.received_at||"WhatsApp mesajı",next:"Gelen mesajı incele ve takip planla",budget:"Belirtilmedi",purpose:"Belirtilmedi",must:"Kriterler müşteriyle doğrulanmalı"});
    if(existing)existing.last=message.received_at||"WhatsApp mesajı";
    await addActivity(env,{customer_id:customer?.id,customer_name:name,kind:"whatsapp_api",body:`Gelen WhatsApp mesajı: ${String(message.body||"").slice(0,2000)}`});
    message.customer_id=customer?.id||null;message.customer_name=name;message.processed=1;
    return{message_id:messageId,processed:1,customer_name:name};
  }
  const message=await env.DB.prepare("SELECT message_id,from_phone,sender_name,body,received_at,processed FROM whatsapp_messages WHERE message_id=? LIMIT 1").bind(messageId).first();
  if(!message){const error=new Error("message_not_found");error.status=404;throw error}
  if(Number(message.processed)!==0){const error=new Error("message_already_reviewed");error.status=409;throw error}
  if(decision==="ignore"){
    const result=await env.DB.prepare("UPDATE whatsapp_messages SET processed=2 WHERE message_id=? AND processed=0").bind(messageId).run();
    if(!result.meta?.changes){const error=new Error("message_already_reviewed");error.status=409;throw error}
    return{message_id:messageId,processed:2};
  }
  const existing=await findCustomerByPhone(env,message.from_phone);
  const name=String(existing?.name||message.sender_name||"WhatsApp müşterisi").trim().slice(0,120)||"WhatsApp müşterisi";
  const statements=[];
  if(!existing)statements.push(env.DB.prepare("INSERT INTO customers (name,phone,need,stage,last_contact,next_step,budget,purpose,must_have) SELECT ?,?,?,?,?,?,?,?,? WHERE EXISTS (SELECT 1 FROM whatsapp_messages WHERE message_id=? AND processed=0) AND NOT EXISTS (SELECT 1 FROM customers WHERE phone=?)").bind(name,message.from_phone,"WhatsApp mesajı • manuel inceleme","Yeni talep",message.received_at||"WhatsApp mesajı","Gelen mesajı incele ve takip planla","Belirtilmedi","Belirtilmedi","Kriterler müşteriyle doğrulanmalı",messageId,message.from_phone));
  else statements.push(env.DB.prepare("UPDATE customers SET last_contact=? WHERE phone=? AND EXISTS (SELECT 1 FROM whatsapp_messages WHERE message_id=? AND processed=0)").bind(message.received_at||"WhatsApp mesajı",existing.phone,messageId));
  statements.push(env.DB.prepare("INSERT INTO activities (customer_id,customer_name,kind,body) SELECT COALESCE(?,(SELECT id FROM customers WHERE phone=? ORDER BY id DESC LIMIT 1)),?,?,? WHERE EXISTS (SELECT 1 FROM whatsapp_messages WHERE message_id=? AND processed=0)").bind(existing?.id||null,message.from_phone,name,"whatsapp_api",`Gelen WhatsApp mesajı: ${String(message.body||"").slice(0,2000)}`,messageId));
  statements.push(env.DB.prepare("UPDATE whatsapp_messages SET customer_id=COALESCE(?,(SELECT id FROM customers WHERE phone=? ORDER BY id DESC LIMIT 1)),processed=1,customer_name=? WHERE message_id=? AND processed=0").bind(existing?.id||null,message.from_phone,name,messageId));
  const results=await env.DB.batch(statements);
  if(!results?.length||!results[results.length-1]?.meta?.changes){const error=new Error("message_already_reviewed");error.status=409;throw error}
  return{message_id:messageId,processed:1,customer_name:name};
}
function normalizeOwner(input){return{name:String(input?.name||"Yeni mal sahibi").slice(0,120),phone:String(input?.phone||"").slice(0,40),area:String(input?.area||"").slice(0,120),property_type:String(input?.property_type||"").slice(0,80),asking_price:String(input?.asking_price||"").slice(0,80),stage:String(input?.stage||"Yeni aday").slice(0,50),next_step:String(input?.next_step||"İlk görüşmeyi planla").slice(0,160),notes:String(input?.notes||"").slice(0,500)}}
async function listOwnerLeads(env){
  if(!env.DB)return memoryOwnerLeads;
  const result=await env.DB.prepare("SELECT id,name,phone,area,property_type,asking_price,stage,next_step,notes,created_at FROM owner_leads ORDER BY id DESC LIMIT 250").all();
  return result.results||[];
}
async function addOwnerLead(env,input){
  const o=normalizeOwner(input);
  if(!env.DB){const lead={id:Date.now(),...o};memoryOwnerLeads.unshift(lead);return lead}
  const result=await env.DB.prepare("INSERT INTO owner_leads (name,phone,area,property_type,asking_price,stage,next_step,notes) VALUES (?,?,?,?,?,?,?,?)").bind(o.name,o.phone,o.area,o.property_type,o.asking_price,o.stage,o.next_step,o.notes).run();
  return {id:result.meta?.last_row_id,...o};
}
async function bulkImportListings(env,input){
  const listings=Array.isArray(input?.listings)?input.listings:[];
  if(!listings.length)invalidPayload(["listings"]);
  const imported=[];const errors=[];
  for(const item of listings){
    try{
      const result=await addListing(env,item);
      imported.push(result);
    }catch(error){
      errors.push({url:item?.url||null,error:error.message||String(error)});
    }
  }
  return {imported:imported.length,received:listings.length,imported,errors};
}

